<?php $edit=query('SELECT * FROM categories WHERE id=?',[(int)($_GET['id']??0)])->fetch()?:[];?>
<div class="page-title"><div><p class="eyebrow">ORGANIZACIJA PONUDE</p><h1>Kategorije</h1><p>Odaberite kategorije na naslovnici i njihov redoslijed.</p></div></div><div class="admin-columns"><section class="panel"><h2><?=$edit?'Uredi kategoriju':'Nova kategorija'?></h2><?php startForm('category',(int)($edit['id']??0));field('name','Naziv',$edit['name']??'');field('slug','Slug (npr. kucni-aparati)',$edit['slug']??'');field('sort_order','Redoslijed na naslovnici (manji broj prvi)',$edit['sort_order']??0,'number');?><label class="checkbox-line"><input type="checkbox" name="show_on_home" <?=!$edit||$edit['show_on_home']?'checked':''?>> Prikaži kategoriju na naslovnici</label><button>Spremi kategoriju</button></form></section><section class="panel"><h2>Registar kategorija</h2><div class="table-scroll"><table><thead><tr><th>Naziv</th><th>Artikli</th><th>Naslovnica</th><th>Redoslijed</th></tr></thead><tbody><?php foreach(query('SELECT c.*,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name')->fetchAll() as $c):?><tr><td><a href="?page=categories&id=<?=$c['id']?>"><?=e($c['name'])?></a><small class="cell-note"><?=e($c['slug'])?></small></td><td><?=$c['total']?></td><td><span class="status-badge <?=$c['show_on_home']?'status-completed':''?>"><?=$c['show_on_home']?'Prikazuje se':'Skrivena'?></span></td><td><?=$c['sort_order']?></td></tr><?php endforeach;?></tbody></table></div></section></div>
